import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"3.0.0-WP04: the L1 migration record","description":"","frontmatter":{},"headers":[],"relativePath":"release/wp04-l1-migration.md","filePath":"release/wp04-l1-migration.md"}'),s={name:"release/wp04-l1-migration.md"};function i(n,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-0-0-wp04-the-l1-migration-record" tabindex="-1">3.0.0-WP04: the L1 migration record <a class="header-anchor" href="#_3-0-0-wp04-the-l1-migration-record" aria-label="Permalink to &quot;3.0.0-WP04: the L1 migration record&quot;">​</a></h1><p>This work package completes the 3.0.0 restructure: every command of the v2.2.0 baseline now runs from ring 3. The L0 side stays a pure service kernel - drivers, services and the numbered L1SVC ABI - and the user plane is the embedded program registry: <strong>one command = one app = one folder</strong> (<code>src/L1/&lt;name&gt;/main.c</code>), discovered mechanically by <code>tools/gen_userprogs.py</code> into the <code>OC_USERPROGS[]</code> registry.</p><h2 id="where-the-251-v2-2-0-commands-went" tabindex="-1">Where the 251 v2.2.0 commands went <a class="header-anchor" href="#where-the-251-v2-2-0-commands-went" aria-label="Permalink to &quot;Where the 251 v2.2.0 commands went&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Batch</th><th>Content</th><th>Count</th></tr></thead><tbody><tr><td>G3-G5</td><td>140 SVC wrappers + 31 file tools + the nano/vi editor shells</td><td>171</td></tr><tr><td>G6</td><td>health / dmesg / logcat / logctl / watchdog</td><td>5</td></tr><tr><td>G7</td><td>the l1 family: run, l1test, ldd, help (+ help_*_test invariants)</td><td>7</td></tr><tr><td>G8</td><td>vitals 5 (mem/frag/heap/sched/syncstat) + crash 3</td><td>8</td></tr><tr><td>G9</td><td>18 ring-0 self-tests (diag ops 9-26)</td><td>18</td></tr><tr><td>G10</td><td>13 chipset diagnostics (diag ops 27-39)</td><td>13</td></tr><tr><td>G11a</td><td>ssh + sshd (the RFC 4251-4254 engine pair, revived verbatim)</td><td>2</td></tr><tr><td>G11b</td><td>ime + ime-test (pinyin engine, DISP ops 11/12 revived)</td><td>2</td></tr><tr><td>G11c</td><td>the nine full-screen TUI pages (category &quot;tui&quot;, 30 files ~13k lines)</td><td>9</td></tr><tr><td>stays in ush</td><td>shell-state builtins (cd/export/alias/...) - a subprocess cannot mutate the shell&#39;s own process state</td><td>9</td></tr><tr><td>subcommands</td><td><code>health export</code> / <code>health watch</code> live inside the health app</td><td>2</td></tr></tbody></table><p>Total migrated: <strong>235 of 251</strong>; the remaining rows are the documented shell-state/<code>subcommand</code> classes above (plus one audit false-positive and the dual-homed counting caliber).</p><h2 id="parity-proof" tabindex="-1">Parity proof <a class="header-anchor" href="#parity-proof" aria-label="Permalink to &quot;Parity proof&quot;">​</a></h2><p>The G13 acceptance matrix ran a 34-command battery against a real v2.2.0 build (same toolchain) side by side in QEMU - structure is line-for-line identical; only volatile state (tick counts, free bytes, heap block counts) and version strings differ. Per-batch evidence (verbatim transcripts, interactive sendkey sessions, VNC page screenshots, the VLM-read desktop menu tree, SSH e2e with paramiko) lives under <code>evidence/3_0_0_wp04_*</code>.</p><h2 id="new-abi-surface-append-only" tabindex="-1">New ABI surface (append-only) <a class="header-anchor" href="#new-abi-surface-append-only" aria-label="Permalink to &quot;New ABI surface (append-only)&quot;">​</a></h2><ul><li>category <strong>19 &quot;diag&quot;</strong> - 39 operations (vitals, crash, self-tests, chipset)</li><li>category <strong>20 &quot;tui&quot;</strong> - 9 operations (the desktop + classic pages)</li><li>net ops <strong>13/14</strong> (ssh/sshd), display ops <strong>11/12</strong> (ime/ime-test, back on their v2.2.0 numbers)</li><li><code>tools/gen_l1svc_ops.py</code> mirrors the numbering to the ring-3 side</li></ul><h2 id="engineering-notes-worth-keeping" tabindex="-1">Engineering notes worth keeping <a class="header-anchor" href="#engineering-notes-worth-keeping" aria-label="Permalink to &quot;Engineering notes worth keeping&quot;">​</a></h2><ul><li><strong>Identity-window discipline</strong>: the kernel image must stay below the 0x400000 boundary (P3-1 security invariant). The GB2312 font tables (~292 KiB) and the 274 embedded programs (515 KiB of ELF payloads) both moved behind per-object gzip containers with lazy inflate into kernel-heap caches - the image shrank while the TUI came back.</li><li><strong>Deterministic builds</strong>: two clean builds minutes apart are byte-identical (gzip <code>mtime=0</code>, xorriso date/GUID pinning, staged tree epoch normalization, FAT date scrubbing, and a post-pass that zeroes the 593 Rock Ridge TF ctime stamps xorriso hardcodes to the assembly moment).</li><li><strong>Interactive ops bypass the text capture</strong>: full-screen pages (tui), session servers (sshd) and the live IME compose line render live on the console/serial; only plain-text ops return through the 4096-byte SVC result buffer.</li></ul><p>Live bugs found and fixed along the way are recorded in the per-batch commit messages and the evidence folders (F6 IRQ-context interrupt enablement, F7 stale RSDP pointer into loader memory, F8 a health format that had drifted from its v2.2.0 source).</p>',12)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
